module D_latch (  
    input wire D,  
    input wire E,  
    input wire R,  
    output reg Q  
);  
    always @ (posedge E or posedge R) begin  
        if (R)  
            Q <= 1'b0;  
        else  
            Q <= D;  
    end  
endmodule

