module watchdog_timer (
    input wire clk,
    input wire reset,
    output reg error
);
    parameter LIMIT = 8'd255; // predefined limit for the watchdog timer
    reg [7:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 8'b0;
            error <= 1'b0;
        end else begin
            if (count < LIMIT) begin
                count <= count + 1;
                error <= 1'b0;
            end else begin
                error <= 1'b1; // signal error if limit reached
            end
        end
    end
endmodule

