module serializer_8bit (  
    input clk,  
    input enable,  
    input [7:0] parallel_in,  
    output reg serial_out  
);  
    reg [2:0] bit_index; // 3 bits to track which bit to serialize  
    reg [7:0] data; // to hold the parallel input data  

    always @(posedge clk) begin  
        if (enable) begin  
            data <= parallel_in;  
            bit_index <= 0;  
        end else if (bit_index < 8) begin  
            serial_out <= data[bit_index];  
            bit_index <= bit_index + 1;  
        end  
    end  
endmodule

