module divide_by_4 (
    input wire clk,
    input wire rst,
    output reg out
);
    reg [1:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 2'b00;
            out <= 1'b0;
        end else begin
            count <= count + 1;
            if (count == 2'b11) begin
                out <= ~out; // Toggle output every 4 clock cycles
            end
        end
    end
endmodule

