module sha256 (  
    input clk,  
    input rst,  
    input start,  
    input [511:0] message,  
    output reg [255:0] hash,  
    output reg done  
);  
    // Internal state variables  
    reg [255:0] h [0:7]; // Hash values  
    reg [511:0] buffer;  
    reg [5:0] state; // State machine for processing  
    reg processing;  

    // Initialization of hash values  
    initial begin  
        h[0] = 32'h6a09e667;  
        h[1] = 32'hbb67ae85;  
        h[2] = 32'h3c6ef372;  
        h[3] = 32'ha54ff53a;  
        h[4] = 32'h510e527f;  
        h[5] = 32'h9b05688c;  
        h[6] = 32'h1f83d9ab;  
        h[7] = 32'h5be0cd19;  
        state = 0;  
        done = 0;  
    end  

    // State machine for processing  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= 0;  
            done <= 0;  
        end else begin  
            case (state)  
                0: begin // Initialization  
                    if (start) begin  
                        buffer <= message;  
                        state <= 1;  
                        processing <= 1;  
                    end  
                end  
                1: begin // Processing (placeholder for the SHA-256 rounds)  
                    // Here, implement the actual compression function steps or data parsing  
                    // For simplicity, we will just move to done state after a cycle  
                    state <= 2;  
                end  
                2: begin // Finalization  
                    // Example: Just output the first hash value for now  
                    hash <= h[0];  
                    done <= 1;  
                    state <= 0;  
                end  
            endcase  
        end  
    end  
endmodule

