        @(posedge clk);
        #1 ack = 0;


        wait(retry == 1);
        @(posedge clk);
        #1 ack = 1;

        @(posedge clk);
        #1 ack = 0;

        #1;


        check_outputs(8'h55, 1'b1, 1'b1);
    end
        endtask

