module switching_regulator(  
    input wire clk,  
    input wire rst,  
    input wire enable,  
    input wire [7:0] v_in,  
    input wire [7:0] v_ref,  
    output reg [7:0] v_out,  
    output reg pwm_signal  
);  

    reg [7:0] error;  
    reg [7:0] duty_cycle;  
    reg [15:0] counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            v_out <= 0;  
            pwm_signal <= 0;  
            duty_cycle <= 0;  
            counter <= 0;  
        end else if (enable) begin  
            error <= v_ref - v_out;  
            duty_cycle <= (error > 0) ? (duty_cycle + 1) : (duty_cycle - 1);  
            if (duty_cycle > 255) duty_cycle <= 255;  
            else if (duty_cycle < 0) duty_cycle <= 0;  
            counter <= counter + 1;  
            if (counter < duty_cycle)  
                pwm_signal <= 1;  
            else  
                pwm_signal <= 0;  
            if (counter == 255) begin  
                counter <= 0;  
                v_out <= v_in * duty_cycle / 255;  
            end  
        end else begin  
            v_out <= 0;  
            pwm_signal <= 0;  
        end  
    end  
endmodule

