module uart_controller (  
    input clk,  
    input rst,  
    input start_tx,  
    input [7:0] data_in,  
    input [1:0] baud_rate,  
    output reg tx  
);  
    reg [3:0] bit_cnt;  
    reg [9:0] shift_reg;  
    reg [15:0] timer;  
    reg transmitting;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            tx <= 1;  
            bit_cnt <= 0;  
            shift_reg <= 0;  
            timer <= 0;  
            transmitting <= 0;  
        end else if (start_tx && !transmitting) begin  
            shift_reg <= {1'b1, data_in, 1'b0}; // stop bit + data + start bit  
            bit_cnt <= 0;  
            timer <= 0;  
            transmitting <= 1;  
        end else if (transmitting) begin  
            timer <= timer + 1;  
            if (timer == (baud_rate == 0 ? 16'd10417 : (baud_rate == 1 ? 16'd5208 : 16'd2604))) begin  
                tx <= shift_reg[bit_cnt];  
                bit_cnt <= bit_cnt + 1;  
                timer <= 0;  
            end  
            if (bit_cnt == 10) begin  
                transmitting <= 0;  
                tx <= 1; // idle state  
            end  
        end  
    end  
endmodule

