module pcie_endpoint (
    input wire clk,
    input wire rst,
    input wire read_req,
    input wire [31:0] addr,
    output reg data_ready,
    output reg [31:0] data_out
);

reg [31:0] data_counter;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        data_ready <= 0;
        data_counter <= 0;
        data_out <= 0;
    end else begin
        if (read_req) begin
            data_ready <= 1;
            data_out <= data_counter;
        end else begin
            data_ready <= 0;
        end
        data_counter <= data_counter + 1;
    end
end

endmodule

