module turbo_decoder(
    input clk,
    input rst,
    input [3:0] received_bits,
    output reg [3:0] decoded_output
);
    reg [1:0] state;
    parameter IDLE = 2'b00, DECODE = 2'b01, OUTPUT = 2'b10;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            decoded_output <= 4'b0000;
        end else begin
            case (state)
                IDLE: begin
                    if (received_bits) begin
                        state <= DECODE;
                    end
                end
                DECODE: begin
                    // Simple decoding logic (for example purposes)
                    decoded_output <= ~received_bits; // Invert the bits for simple decoding
                    state <= OUTPUT;
                end
                OUTPUT: begin
                    // Output the decoded bits
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

module SR_latch (  
    input S,  
    input R,  
    output reg Q,  
    output reg Q_bar  
);  
    always @ (S or R) begin  
        if (S && !R) begin  
            Q <= 1;  
            Q_bar <= 0;  
        end else if (!S && R) begin  
            Q <= 0;  
            Q_bar <= 1;  
        end  
        // Retain previous state when both S and R are low  
    end  
endmodule

