module up_counter #(parameter MAX_COUNT = 5) (
    input clk,
    input rst,
    output reg [2:0] count // 3 bits to count from 0 to 5
);
    always @(posedge clk or posedge rst) begin
        if (rst)
            count <= 0;
        else if (count == MAX_COUNT)
            count <= 0;
        else
            count <= count + 1;
    end
endmodule

module black_scholes(  
    input [31:0] S,  // Stock Price  
    input [31:0] K,  // Strike Price  
    input [31:0] T,  // Time to expiration  
    input [31:0] r,  // Risk-free interest rate  
    input [31:0] sigma,  // Volatility  
    output [31:0] call_price  // Call option price  
);  
    // Simple implementation using a made-up formula for demonstration.  
    // In real scenarios, you would implement the full Black-Scholes formula.  
    // For example: call_price = S * N(d1) - K * exp(-r * T) * N(d2)  
    // Here we will assume a simple linear approximation for the sake of example.  
    assign call_price = (S - K) * (T / 1000) + (r * S) / 100;  
endmodule

module siso_shift_register(  
    input clk,  
    input rst,  
    input serial_in,  
    output reg serial_out  
);  
    parameter WIDTH = 5;  
    reg [WIDTH-1:0] shift_reg;  

    always @(posedge clk or posedge rst) begin  
        if (rst)  
            shift_reg <= 0;  
        else begin  
            shift_reg <= {shift_reg[WIDTH-2:0], serial_in};  
            serial_out <= shift_reg[WIDTH-1];  
        end  
    end  
endmodule

module crystal_oscillator #(parameter N = 4) (  
    input clk,  
    input rst,  
    output reg out  
);  
    reg [31:0] count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            count <= 0;  
            out <= 0;  
        end else begin  
            if (count == N-1) begin  
                out <= ~out;  
                count <= 0;  
            end else begin  
                count <= count + 1;  
            end  
        end  
    end  
endmodule

module fifo_queue #(parameter DEPTH = 4, WIDTH = 8) (  
    input clk,  
    input rst_n,  
    input [WIDTH-1:0] data_in,  
    input wr_en,  
    input rd_en,  
    output reg [WIDTH-1:0] data_out,  
    output reg full,  
    output reg empty  
);  
    reg [WIDTH-1:0] memory [0:DEPTH-1];  
    reg [3:0] head, tail;  
    reg [3:0] count;  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            head <= 0;  
            tail <= 0;  
            count <= 0;  
            full <= 0;  
            empty <= 1;  
        end else begin  
            if (wr_en && !full) begin  
                memory[tail] <= data_in;  
                tail <= (tail + 1) % DEPTH;  
                count <= count + 1;  
            end  
            if (rd_en && !empty) begin  
                data_out <= memory[head];  
                head <= (head + 1) % DEPTH;  
                count <= count - 1;  
            end  
            full <= (count == DEPTH);  
            empty <= (count == 0);  
        end  
    end  
endmodule

