module pipeline_processor(  
    input clk,  
    input rst,  
    input [7:0] data1,  
    input [7:0] data2,  
    output reg [7:0] result  
);  
    reg [7:0] IF_data1, IF_data2;  
    reg [7:0] ID_data1, ID_data2;  
    reg [7:0] EX_result;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            IF_data1 <= 0;  
            IF_data2 <= 0;  
            ID_data1 <= 0;  
            ID_data2 <= 0;  
            EX_result <= 0;  
            result <= 0;  
        end else begin  
            // Instruction Fetch Stage  
            IF_data1 <= data1;  
            IF_data2 <= data2;  

            // Instruction Decode Stage  
            ID_data1 <= IF_data1;  
            ID_data2 <= IF_data2;  

            // Execute Stage  
            EX_result <= ID_data1 + ID_data2;  

            // Memory Access Stage (No operation in this example)  
            // Write Back Stage  
            result <= EX_result;  
        end  
    end  
endmodule

module flash_memory_cell(  
    input wire D,  
    input wire WE,  
    input wire RE,  
    output reg Q  
);  
    always @(posedge WE or posedge RE) begin  
        if (WE)  
            Q <= D;  
        else if (RE)  
            Q <= Q;  
    end  
endmodule

