module fixed_priority_arbiter (
    input wire clk,
    input wire rst,
    input wire req0,
    input wire req1,
    input wire req2,
    output reg grant0,
    output reg grant1,
    output reg grant2
);
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            grant0 <= 0;
            grant1 <= 0;
            grant2 <= 0;
        end else begin
            grant0 <= req0 && !grant1 && !grant2;
            grant1 <= req1 && !grant0 && !grant2;
            grant2 <= req2 && !grant0 && !grant1;
            if (grant0) begin
                grant1 <= 0;
                grant2 <= 0;
            end else if (grant1) begin
                grant2 <= 0;
            end else if (grant2) begin
                grant0 <= 0;
                grant1 <= 0;
            end
        end
    end
endmodule

module simple_des_encryption(  
    input wire clk,  
    input wire rst,  
    input wire [63:0] data_in,  
    input wire [31:0] key,  
    output reg [63:0] data_out  
);  

reg [31:0] left_half, right_half;  

always @(posedge clk or posedge rst) begin  
    if (rst) begin  
        data_out <= 64'b0;  
    end else begin  
        left_half <= data_in[63:32] ^ key;  
        right_half <= data_in[31:0] ^ key;  
        left_half <= {left_half[30:0], left_half[31]}; // shift left  
        right_half <= {right_half[0], right_half[31:1]}; // rotate right  
        data_out <= {left_half, right_half};  
    end  
end  
endmodule

