module dma_controller(
    input clk,
    input reset,
    input start,
    input [15:0] src_addr,
    input [15:0] dest_addr,
    input [3:0] transfer_count,
    output reg [7:0] data_out,
    output reg complete,
    output reg [15:0] current_src_addr,
    output reg [15:0] current_dest_addr
);
    reg [3:0] count;
    reg transferring;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            current_src_addr <= src_addr;
            current_dest_addr <= dest_addr;
            complete <= 1'b0;
            transferring <= 1'b0;
            data_out <= 8'b0;
        end else if (start && !transferring) begin
            transferring <= 1'b1;
            count <= transfer_count;
            complete <= 1'b0;
        end else if (transferring) begin
            if (count > 0) begin
                // Simulate data transfer (for simplicity we're just outputting the address here)
                data_out <= current_src_addr[7:0]; // get lower byte of src_addr as data
                current_src_addr <= current_src_addr + 1;
                current_dest_addr <= current_dest_addr + 1;
                count <= count - 1;
            end else begin
                transferring <= 1'b0;
                complete <= 1'b1;
            end
        end
    end
endmodule

